import{_ as e,o,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"setup函数","description":"在 Pinia 中，​ 同一个 Store 只会被初始化一次 ，即使你在多个页面中多次引入并调用 useCountryStore() ，​ 箭头函数内部的逻辑不会重复执行 。以下是详细解释： 1. ​ Pinia Store 的单例特性 Pinia 的 Store 是 全局单例。","frontmatter":{"title":"setup函数","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"在 Pinia 中，​ 同一个 Store 只会被初始化一次 ，即使你在多个页面中多次引入并调用 useCountryStore() ，​ 箭头函数内部的逻辑不会重复执行 。以下是详细解释： 1. ​ Pinia Store 的单例特性 Pinia 的 Store 是 全局单例。","sidebarWeight":102,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/数据流/setup函数.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/setup函数.md","filePath":"posts/Vue系统教程/04-路由与状态管理/setup函数.md"}'),a={name:"posts/Vue系统教程/04-路由与状态管理/setup函数.md"};function n(i,t,c,u,l,g){return o(),r("div",null,[...t[0]||(t[0]=[s('<div><h1 id="setup函数" tabindex="-1">setup函数 <a class="header-anchor" href="#setup函数" aria-label="Permalink to &quot;setup函数&quot;">​</a></h1><blockquote><p>本节目标：理解“setup函数”的核心思路，并能把它用于实际开发或面试表达。 ==在 Pinia 中，​==<strong>同一个 Store 只会被初始化一次</strong>==，即使你在多个页面中多次引入并调用== ==useCountryStore()====，​==<strong>箭头函数内部的逻辑不会重复执行</strong>==。以下是详细解释：==</p></blockquote><p><strong>1. ​****Pinia Store 的单例特性</strong> ==Pinia 的 Store 是==<strong>全局单例</strong>==的：==</p><ul><li>==第一次调用== ==useCountryStore()== ==时，Pinia 会执行传入的== ==setup== ==函数（即你的箭头函数），初始化 Store 的状态（====data====、====loading====、====fetchData====）。==</li><li>==后续在任何页面/组件中调用== ==useCountryStore()====，Pinia 会直接返回==<strong>已创建的 Store 实例</strong>==，​==<strong>不会重新执行箭头函数</strong>==。==</li></ul><p><strong>示例代码验证：</strong></p><p>==javascript== ==复制== <em>// 页面A</em>======const== ==storeA== ===== ==useCountryStore====();========console====.====log====(storeA.data);== <em>// 第一次初始化，执行箭头函数</em>==== <em>// 页面B</em>======const== ==storeB== ===== ==useCountryStore====();========console====.====log====(storeB.data);== <em>// 直接返回已有的 storeA，不会执行箭头函数</em>==== ==console====.====log====(storeA== ======= ==storeB);== <em>// true，同一个实例</em></p><p><strong>2. ​</strong>useFetchListData 的行为**** ==如果== ==useFetchListData== ==是一个自定义 Hook（如基于== ==useFetch== ==或== ==axios== ==的封装）：==</p><ul><li>==​==<strong>首次调用</strong> <strong>useCountryStore()</strong> <strong>时</strong>==：====useFetchListData== ==会执行，发起网络请求（如== ==fetchData== ==被调用）。==</li><li>==​==<strong>后续调用</strong> <strong>useCountryStore()</strong> <strong>时</strong>==：====useFetchListData== ==​==<strong>不会重复执行</strong>==，因为 Store 已经初始化完成，直接复用已有的== ==data====、====loading== ==和== ==fetchData== ==方法。==</li></ul><p><strong>关键点：</strong></p><ul><li>==​**====data== ==和== ==loading== ==是响应式状态**：它们会被 Pinia 持久化，跨组件共享。==</li><li>==​**====fetchData== ==方法是稳定的**：多次调用== ==store.fetchData()== ==会触发请求，但方法本身不会重复创建。== <strong>3. ​****需要警惕的边界情况</strong> ==虽然 Store 是单例的，但以下场景可能导致意外行为：== <strong>​</strong>(1) 动态修改 url**** ==如果你的== ==useFetchListData== ==的== ==url== ==是动态的（例如从参数传入），需要在 Store 外部维护状态：==</li></ul><p>==javascript== ==复制== ==const== ==useCountryStore== ===== ==defineStore====(====&#39;country&#39;====, ()== ===&gt;== =={====== ==const== ==url== ===== ==ref====(====&#39;/new-api/pub/get_country&#39;====);== <em>// 将 url 转为响应式</em>==== ==const== =={ loading, data, fetchData }== ===== ==useFetchListData====({== ==url====:== ==url.value });====== ==return== =={ data, loading, fetchData };========});== <strong>​</strong>(2) Store 被卸载后重新挂载**** ==Pinia Store 默认是持久化的，但如果手动调用== ==$dispose()== ==或页面强制刷新，Store 会被销毁，下次调用== ==useCountryStore()== ==时会重新初始化。==</p><p><strong>4. ​****最佳实践建议</strong><strong>​</strong>(1) 明确数据加载时机****</p><ul><li>==在应用入口（如== ==App.vue====）或路由守卫中提前调用== ==store.fetchData()====，避免多页面重复请求。==</li><li>==如果数据需要实时更新，可以在== ==fetchData== ==中增加逻辑：============javascript========复制========const== ==fetchData== ===== ==async== ==()== ===&gt;== =={====== ==if== ==(====Date====.====now====()== ==-== ==lastFetchTime== ==&gt;== ==60_000====) {== <em>// 60秒缓存</em>==== ==await== ==doFetch====();====== ==}========};==</li></ul><p><strong>​</strong>(2) 使用 storeToRefs 解构**** ==在组件中解构 Store 时，使用== ==storeToRefs== ==保持响应性：==</p><p>==javascript== ==复制== ==import== =={ storeToRefs }== ==from== ==&#39;pinia&#39;====;====== ==const== ==store== ===== ==useCountryStore====();========const== =={ data, loading }== ===== ==storeToRefs====(store);== <em>// 保持响应式</em></p><p><strong>总结</strong></p><ul><li>==​==<strong>不会重复执行</strong>==：多次调用== ==useCountryStore()== ==不会重复执行箭头函数内部的逻辑。==</li><li>==​==<strong>共享同一份状态</strong>==：所有组件访问的是同一个 Store 实例，状态自动同步。==</li><li>==​==<strong>注意方法调用</strong>==：====fetchData()== ==方法可以被多次调用（触发请求），但方法本身是稳定的。==</li></ul><p>==如有其他边界场景，可以提供更多代码细节进一步分析！== &gt; 来自 &lt;<a href="https://yuanbao.tencent.com/chat/naQivTmsDa/c7b22caa-07c3-42e3-b382-8d6c298d5c4c" target="_blank" rel="noreferrer">https://yuanbao.tencent.com/chat/naQivTmsDa/c7b22caa-07c3-42e3-b382-8d6c298d5c4c</a>&gt; &gt; 来自 &lt;<a href="https://yuanbao.tencent.com/chat/naQivTmsDa/c7b22caa-07c3-42e3-b382-8d6c298d5c4c" target="_blank" rel="noreferrer">https://yuanbao.tencent.com/chat/naQivTmsDa/c7b22caa-07c3-42e3-b382-8d6c298d5c4c</a>&gt;</p></div>',1)])])}const h=e(a,[["render",n]]);export{d as __pageData,h as default};
